def find_anagrams(s, p):
    p_count = [0] * 26
    s_count = [0] * 26
    for c in p:
        p_count[ord(c) - ord('a')] += 1
    result = []
    for i in range(len(s) - len(p) + 1):
        s_count[ord(s[i]) - ord('a')] += 1
        if i >= len(p):
            s_count[ord(s[i - len(p)]) - ord('a')] -= 1
        if p_count == s_count:
            result.append(i)
    return result

