            val = -heapq.heappop(self.small)
            heapq.heappush(self.large, val)

import heapq
class KthLargest:
    def __init__(self, k, nums):
        self.k = k
        self.heap = nums
        heapq.heapify(self.heap)
        while len(self.heap) > k:
            heapq.heappop(self.heap)
    def add(self, val):
        if len(self.heap) < self.k:
            heapq.heappush(self.heap, val)
        elif val > self.heap[0]:
            heapq.heapreplace(self.heap, val)
        return self.heap[0]

def fib(n, memo={}):
    if n in memo:
        return memo[n]
    if n <= 1:
        return n
    memo[n] = fib(n-1,memo) + fib(n-2,memo)
    return memo[n]

def fib(n):
    if n <= 1:
        return n
    dp = [0] * (n + 1)
    dp[1] = 1
    for i in range(2, n + 1):
        dp[i] = dp[i-1] + dp[i-2]
    return dp[n]

def knapsack(w, v, cap):
    n = len(w)
    dp = [[0]*(cap+1) for _ in range(n+1)]
    for i in range(1, n+1):
        for c in range(cap+1):
            if w[i-1] <= c:
                dp[i][c] = max(v[i-1]+dp[i-1][c-w[i-1]], dp[i-1][c])
            else:
                dp[i][c] = dp[i-1][c]
    return dp[n][cap]

def unbounded(w, v, cap):
    dp = [0] * (cap + 1)
    for i in range(len(w)):
        for c in range(w[i], cap + 1):
            dp[c] = max(dp[c], v[i] + dp[c - w[i]])
    return dp[cap]

def coin_change(coins, amt):
    dp = [float('inf')] * (amt + 1)
    dp[0] = 0
    for i in range(1, amt + 1):
        for coin in coins:
            if coin <= i:
                dp[i] = min(dp[i], 1 + dp[i - coin])
    return dp[amt] if dp[amt] != float('inf') else -1

def change(amt, coins):
    dp = [0] * (amt + 1)
    dp[0] = 1
    for coin in coins:
        for i in range(coin, amt + 1):
            dp[i] += dp[i - coin]
    return dp[amt]

def lis(arr):
