def is_valid_sudoku(b):
    rows = [set() for _ in range(9)]
    cols = [set() for _ in range(9)]
    boxes = [set() for _ in range(9)]
    for i in range(9):
        for j in range(9):
            if b[i][j] != '.':
                val = b[i][j]
                if val in rows[i] or val in cols[j] or val in boxes[i//3*3+j//3]:
                    return False
                rows[i].add(val)
                cols[j].add(val)
                boxes[i//3*3+j//3].add(val)
    return True

